+}
+
+type Task struct {
+	ID             string    `json:"id"`
+	RunID          string    `json:"run_id"`
+	State          TaskState `json:"state"`
+	Revision       uint64    `json:"revision"`
+	MaxAttempts    uint32    `json:"max_attempts"`
+	CurrentAttempt uint32    `json:"current_attempt"`
