package workflow

import (
	"errors"
	"testing"

	"github.com/google/uuid"
)

func planningReviewRun(t *testing.T) Run {
	t.Helper()
	run := createTestRun(t)
	var err error
	run, _, err = run.Apply(ProposeSpecification{
		Meta: envelope(ActorWorkflowService, run.Revision),
		ID: run.ID, Specification: testSpec,
	})
	if err != nil {
		t.Fatal(err)
	}
	run, _, err = run.Apply(ApproveSpecification{
		Meta: envelope(ActorHuman, run.Revision), ID: run.ID, Specification: testSpec,
	})
	if err != nil {
		t.Fatal(err)
	}
	graph := ArtifactRef{
		URI: "artifact://task-graphs/v1",
		Digest: "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc",
	}
	run, _, err = run.Apply(ProposeTaskGraph{
		Meta: envelope(ActorWorkflowService, run.Revision), ID: run.ID, TaskGraph: graph,
	})
	if err != nil {
		t.Fatal(err)
	}
	return run
}

func TestTaskGraphApprovalCreatesReadyRootsAndPendingDependents(t *testing.T) {
	run := planningReviewRun(t)
	rootID, dependentID := uuid.NewString(), uuid.NewString()
	decision, err := run.ApproveTaskGraph(ApproveTaskGraph{
		Meta: envelope(ActorHuman, run.Revision), ID: run.ID, TaskGraph: *run.TaskGraph,
		Tasks: []TaskDefinition{
			{ID: rootID, MaxAttempts: 2},
			{ID: dependentID, MaxAttempts: 3},
		},
		Dependencies: []TaskDependency{{TaskID: dependentID, DependsOnID: rootID}},
	})
	if err != nil {
		t.Fatal(err)
	}
	if decision.Run.State != RunStateReady || len(decision.Tasks) != 2 ||
		decision.Tasks[0].State != TaskStateReady ||
		decision.Tasks[1].State != TaskStatePending {
		t.Fatalf("unexpected decision: %#v", decision)
	}
	if len(decision.Events) != 3 || decision.Events[0].Type != "TASK_GRAPH_APPROVED" ||
		decision.Events[1].Type != "TASK_READY" ||
		decision.Events[2].Type != "TASK_CREATED" {
		t.Fatalf("unexpected events: %#v", decision.Events)
	}
}

func TestTaskGraphApprovalRejectsCyclesWithoutPartialOutput(t *testing.T) {
	run := planningReviewRun(t)
	first, second := uuid.NewString(), uuid.NewString()
	decision, err := run.ApproveTaskGraph(ApproveTaskGraph{
		Meta: envelope(ActorHuman, run.Revision), ID: run.ID, TaskGraph: *run.TaskGraph,
		Tasks: []TaskDefinition{{ID: first, MaxAttempts: 1}, {ID: second, MaxAttempts: 1}},
		Dependencies: []TaskDependency{
			{TaskID: first, DependsOnID: second},
			{TaskID: second, DependsOnID: first},
		},
	})
	if !errors.Is(err, ErrInvalid) {
		t.Fatalf("error = %v", err)
	}
	if decision.Run.ID != "" || decision.Tasks != nil || decision.Events != nil {
		t.Fatalf("partial decision: %#v", decision)
	}
}

func TestTaskGraphRejectionRequiresHumanAndBinding(t *testing.T) {
	run := planningReviewRun(t)
	for _, kind := range []ActorKind{ActorModel, ActorPython, ActorWorkflowService} {
		next, events, err := run.Apply(RejectTaskGraph{
			Meta: envelope(kind, run.Revision), ID: run.ID,
			TaskGraph: *run.TaskGraph, Reason: "needs work",
		})
		if !errors.Is(err, ErrUnauthorized) || next.ID != "" || events != nil {
			t.Fatalf("kind %s: %#v %#v %v", kind, next, events, err)
		}
	}
	next, events, err := run.Apply(RejectTaskGraph{
		Meta: envelope(ActorHuman, run.Revision), ID: run.ID,
		TaskGraph: *run.TaskGraph, Reason: "needs work",
	})
	if err != nil || next.State != RunStateTaskPlanning ||
		len(events) != 1 || events[0].Type != "TASK_GRAPH_REJECTED" {
		t.Fatalf("unexpected rejection: %#v %#v %v", next, events, err)
	}
}

package workflow

import (
	"fmt"
	"time"

	"github.com/google/uuid"
)

type TaskDefinition struct {
	ID          string `json:"task_id"`
	MaxAttempts uint32 `json:"max_attempts"`
}

type TaskDependency struct {
	TaskID      string `json:"task_id"`
	DependsOnID string `json:"depends_on_id"`
}

type Task struct {
	ID             string    `json:"id"`
	RunID          string    `json:"run_id"`
	State          TaskState `json:"state"`
	Revision       uint64    `json:"revision"`
	MaxAttempts    uint32    `json:"max_attempts"`
	CurrentAttempt uint32    `json:"current_attempt"`
	CreatedAt      time.Time `json:"created_at"`
	UpdatedAt      time.Time `json:"updated_at"`
}

func (t Task) Validate() error {
	if err := validateID("task", t.ID); err != nil {
		return err
	}
	if err := validateID("run", t.RunID); err != nil {
		return err
	}
	if err := t.State.Validate(); err != nil {
		return err
	}
	if t.Revision == 0 || t.MaxAttempts == 0 || t.CurrentAttempt > t.MaxAttempts ||
		t.CreatedAt.IsZero() || t.UpdatedAt.IsZero() {
		return fmt.Errorf("%w: task snapshot", ErrInvalid)
	}
	return nil
}

func NewPlannedTasks(
	runID string,
	definitions []TaskDefinition,
	dependencies []TaskDependency,
	meta CommandEnvelope,
) ([]Task, []TaskDependency, []Event, error) {
	if err := validateID("run", runID); err != nil {
		return nil, nil, nil, err
	}
	if len(definitions) == 0 {
		return nil, nil, nil, fmt.Errorf("%w: empty task graph", ErrInvalid)
	}
	taskIDs := make(map[string]struct{}, len(definitions))
	for _, definition := range definitions {
		if err := validateID("task", definition.ID); err != nil {
			return nil, nil, nil, err
		}
		if definition.MaxAttempts == 0 {
			return nil, nil, nil, fmt.Errorf("%w: max attempts", ErrInvalid)
		}
		if _, exists := taskIDs[definition.ID]; exists {
			return nil, nil, nil, fmt.Errorf("%w: duplicate task", ErrInvalid)
		}
		taskIDs[definition.ID] = struct{}{}
	}

	incoming := make(map[string]int, len(definitions))
	adjacency := make(map[string][]string, len(definitions))
	edges := make(map[string]struct{}, len(dependencies))
	for _, dependency := range dependencies {
		if _, exists := taskIDs[dependency.TaskID]; !exists {
			return nil, nil, nil, fmt.Errorf("%w: dependency task", ErrInvalid)
		}
		if _, exists := taskIDs[dependency.DependsOnID]; !exists {
			return nil, nil, nil, fmt.Errorf("%w: dependency target", ErrInvalid)
		}
		if dependency.TaskID == dependency.DependsOnID {
			return nil, nil, nil, fmt.Errorf("%w: self dependency", ErrInvalid)
		}
		key := dependency.TaskID + ":" + dependency.DependsOnID
		if _, exists := edges[key]; exists {
			return nil, nil, nil, fmt.Errorf("%w: duplicate dependency", ErrInvalid)
		}
		edges[key] = struct{}{}
		incoming[dependency.TaskID]++
		adjacency[dependency.DependsOnID] = append(adjacency[dependency.DependsOnID], dependency.TaskID)
	}
	queue := make([]string, 0, len(definitions))
	degrees := make(map[string]int, len(incoming))
	for id := range taskIDs {
		degrees[id] = incoming[id]
		if incoming[id] == 0 {
			queue = append(queue, id)
		}
	}
	visited := 0
	for len(queue) > 0 {
		id := queue[0]
		queue = queue[1:]
		visited++
		for _, dependent := range adjacency[id] {
			degrees[dependent]--
			if degrees[dependent] == 0 {
				queue = append(queue, dependent)
			}
		}
	}
	if visited != len(definitions) {
		return nil, nil, nil, fmt.Errorf("%w: cyclic task graph", ErrInvalid)
	}

	tasks := make([]Task, 0, len(definitions))
	events := make([]Event, 0, len(definitions))
	for _, definition := range definitions {
		state := TaskStatePending
		eventType := "TASK_CREATED"
		if incoming[definition.ID] == 0 {
			state = TaskStateReady
			eventType = "TASK_READY"
		}
		task := Task{
			ID: definition.ID, RunID: runID, State: state, Revision: 1,
			MaxAttempts: definition.MaxAttempts, CreatedAt: meta.Timestamp.UTC(),
			UpdatedAt: meta.Timestamp.UTC(),
		}
		tasks = append(tasks, task)
		eventID := uuid.NewSHA1(
			uuid.MustParse(meta.CommandID),
			[]byte(definition.ID+":"+eventType),
		).String()
		events = append(events, Event{
			ID: eventID, AggregateType: "TASK", AggregateID: task.ID,
			Revision: 1, Type: eventType, Timestamp: meta.Timestamp.UTC(),
			Actor: meta.Actor, CorrelationID: meta.CorrelationID,
			CausationID: meta.CausationID,
			Payload: map[string]any{"run_id": runID, "max_attempts": definition.MaxAttempts},
		})
	}
	return tasks, append([]TaskDependency(nil), dependencies...), events, nil
}

