+func loadTask(ctx context.Context, tx pgx.Tx, runID, taskID string) (Task, error) {
+	var task Task
+	var leaseID, leaseOwner *string
+	var leaseExpiry *time.Time
+	var proposalURI, proposalDigest, executionURI, executionDigest *string
+	var candidateCommit *string
+	var verificationURI, verificationDigest, reviewURI, reviewDigest *string
+	var approvalURI, approvalDigest *string
+	err := tx.QueryRow(ctx, `SELECT task_id,run_id,state,revision,max_attempts,current_attempt,
+		lease_id,lease_owner_id,lease_expires_at,proposal_uri,proposal_digest,
+		execution_uri,execution_digest,candidate_commit,verification_uri,verification_digest,
+		review_uri,review_digest,approval_uri,approval_digest,created_at,updated_at
+		FROM workflow_tasks WHERE run_id=$1 AND task_id=$2 FOR UPDATE`,
+		runID, taskID).Scan(
+		&task.ID, &task.RunID, &task.State, &task.Revision, &task.MaxAttempts,
+		&task.CurrentAttempt, &leaseID, &leaseOwner, &leaseExpiry,
+		&proposalURI, &proposalDigest, &executionURI, &executionDigest,
+		&candidateCommit, &verificationURI, &verificationDigest,
+		&reviewURI, &reviewDigest, &approvalURI, &approvalDigest,
+		&task.CreatedAt, &task.UpdatedAt)
+	if errors.Is(err, pgx.ErrNoRows) {
+		return Task{}, ErrNotFound
+	}
+	if err != nil {
+		return Task{}, fmt.Errorf("load task: %w", err)
+	}
+	if leaseID != nil || leaseOwner != nil || leaseExpiry != nil {
+		if leaseID == nil || leaseOwner == nil || leaseExpiry == nil {
+			return Task{}, fmt.Errorf("%w: partial lease", ErrInvalid)
+		}
+		task.Lease = &LeaseRef{ID: *leaseID, OwnerID: *leaseOwner, ExpiresAt: *leaseExpiry}
+	}
+	task.Proposal, err = optionalArtifact(proposalURI, proposalDigest)
+	if err != nil {
+		return Task{}, err
+	}
+	task.Execution, err = optionalArtifact(executionURI, executionDigest)
+	if err != nil {
+		return Task{}, err
+	}
+	task.Verification, err = optionalArtifact(verificationURI, verificationDigest)
+	if err != nil {
+		return Task{}, err
+	}
+	task.Review, err = optionalArtifact(reviewURI, reviewDigest)
+	if err != nil {
+		return Task{}, err
+	}
+	task.Approval, err = optionalArtifact(approvalURI, approvalDigest)
+	if err != nil {
+		return Task{}, err
+	}
+	if candidateCommit != nil {
+		task.CandidateCommit = *candidateCommit
+	}
+	if err := task.Validate(); err != nil {
+		return Task{}, err
+	}
+	return task, nil
+}
