func (r Run) applyCompletion(command RunCommand) (Run, []Event, error) {
	meta, next := command.Envelope(), r
	var eventType string
	switch command := command.(type) {
	case StartRun:
		if r.State != RunStateReady { return Run{}, nil, ErrInvalidTransition }
		if meta.Actor.Kind != ActorWorkflowService { return Run{}, nil, ErrUnauthorized }
		next.State, eventType = RunStateExecuting, "RUN_EXECUTION_STARTED"
	case RecordRunExecution:
		if r.State != RunStateExecuting { return Run{}, nil, ErrInvalidTransition }
		if meta.Actor.Kind != ActorExecutionService { return Run{}, nil, ErrUnauthorized }
		if err := command.Execution.Validate(); err != nil || !commitPattern.MatchString(command.CandidateCommit) {
			return Run{}, nil, fmt.Errorf("%w: run execution binding", ErrInvalid)
		}
		execution := command.Execution
		next.Execution, next.CandidateCommit = &execution, command.CandidateCommit
		next.State, eventType = RunStateVerifying, "RUN_EXECUTED"
	case RecordRunVerification:
		if r.State != RunStateVerifying { return Run{}, nil, ErrInvalidTransition }
		if meta.Actor.Kind != ActorVerificationService { return Run{}, nil, ErrUnauthorized }
		if command.CandidateCommit != r.CandidateCommit { return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid) }
		if err := command.Evidence.Validate(); err != nil { return Run{}, nil, err }
		evidence := command.Evidence
		next.Verification, next.State, eventType = &evidence, RunStateReviewing, "RUN_VERIFIED"
	case RecordRunReview:
		if r.State != RunStateReviewing { return Run{}, nil, ErrInvalidTransition }
		if meta.Actor.Kind != ActorReviewService { return Run{}, nil, ErrUnauthorized }
		if command.CandidateCommit != r.CandidateCommit { return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid) }
		if err := command.Review.Validate(); err != nil { return Run{}, nil, err }
		review := command.Review
		next.Review, next.State, eventType = &review, RunStateAwaitingApproval, "RUN_REVIEWED"
	case ApproveRun:
		if r.State != RunStateAwaitingApproval { return Run{}, nil, ErrInvalidTransition }
		if meta.Actor.Kind != ActorHuman { return Run{}, nil, ErrUnauthorized }
		if command.CandidateCommit != r.CandidateCommit { return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid) }
		if err := validateBoundArtifact(r.Review, command.Review, "run review"); err != nil { return Run{}, nil, err }
		if err := command.Approval.Validate(); err != nil { return Run{}, nil, err }
		approval := command.Approval
		next.Approval, next.State, eventType = &approval, RunStateMergeReady, "RUN_APPROVED"
	case RejectRun:
		if r.State != RunStateAwaitingApproval { return Run{}, nil, ErrInvalidTransition }
		if meta.Actor.Kind != ActorHuman { return Run{}, nil, ErrUnauthorized }
		if command.CandidateCommit != r.CandidateCommit { return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid) }
		if err := validateBoundArtifact(r.Review, command.Review, "run review"); err != nil { return Run{}, nil, err }
		if err := validateReason(command.Reason); err != nil { return Run{}, nil, err }
		next.State, eventType = RunStateRejected, "RUN_REJECTED"
	case RecordMerge:
		if r.State != RunStateMergeReady { return Run{}, nil, ErrInvalidTransition }
		if meta.Actor.Kind != ActorMergeService { return Run{}, nil, ErrUnauthorized }
		if command.CandidateCommit != r.CandidateCommit { return Run{}, nil, fmt.Errorf("%w: run candidate commit", ErrInvalid) }
		if err := validateBoundArtifact(r.Approval, command.Approval, "run approval"); err != nil { return Run{}, nil, err }
		if err := command.Merge.Validate(); err != nil { return Run{}, nil, err }
		merge := command.Merge
		next.Merge, next.State, eventType = &merge, RunStateMerged, "RUN_MERGED"
	case FailRun:
		if !trustedOperationalActor(meta.Actor.Kind) { return Run{}, nil, ErrUnauthorized }
		if err := command.Evidence.Validate(); err != nil { return Run{}, nil, err }
		if err := validateReason(command.Reason); err != nil { return Run{}, nil, err }
		next.State, eventType = RunStateFailed, "RUN_FAILED"
	case CancelRun:
		if meta.Actor.Kind != ActorHuman { return Run{}, nil, ErrUnauthorized }
		if err := validateReason(command.Reason); err != nil { return Run{}, nil, err }
		next.State, eventType = RunStateCancelled, "RUN_CANCELLED"
	default:
		return Run{}, nil, fmt.Errorf("%w: unsupported completion command", ErrInvalid)
	}
	next.Revision++
	next.UpdatedAt = meta.Timestamp.UTC()
	return next, []Event{newRunEvent(next, meta, eventType, nil)}, nil
}

