+			Timestamp: meta.Timestamp.UTC(), Actor: meta.Actor,
+			CorrelationID: meta.CorrelationID, CausationID: meta.CausationID,
+			Payload: map[string]any{"run_id": runID, "reason": reason},
+		})
+	}
+	return events, nil
