+func TestTaskRetriesAndAttemptExhaustion(t *testing.T) {
+	task := readyTask()
+	task.MaxAttempts = 1
+	lease := LeaseRef{
+		ID: uuid.NewString(), OwnerID: uuid.NewString(), ExpiresAt: testTime.Add(time.Hour),
+	}
