	if result, found, err := loadCommandResult(ctx, tx, command.Envelope().CommandID, digest); err != nil {
		return CommandResult{}, err
	} else if found {
		result.Replay = true
		return result, tx.Commit(ctx)
	}

	var current Run
	if create, ok := command.(CreateRun); ok {
