	incoming := make(map[string]int, len(definitions))
	adjacency := make(map[string][]string, len(definitions))
	edges := make(map[string]struct{}, len(dependencies))
	for _, dependency := range dependencies {
		if _, exists := taskIDs[dependency.TaskID]; !exists {
			return nil, nil, nil, fmt.Errorf("%w: dependency task", ErrInvalid)
		}
		if _, exists := taskIDs[dependency.DependsOnID]; !exists {
